import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as HoverCard from "../../ui/hover-card";

// MODEL

export const Model = S.Struct({
  open: S.Boolean,
});
export type Model = typeof Model.Type;

// MESSAGE

export const OpenedHoverCard = m("OpenedHoverCard");
export const ClosedHoverCard = m("ClosedHoverCard");
export const Message = S.Union([OpenedHoverCard, ClosedHoverCard]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ open: false }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      OpenedHoverCard: () => [evo(model, { open: () => true }), []],
      ClosedHoverCard: () => [evo(model, { open: () => false }), []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return HoverCard.rootView<Message>({
    children: [
      HoverCard.triggerView<Message>({
        open: model.open,
        onOpen: OpenedHoverCard(),
        children: [h.span([], ["Hover Here"])],
      }),
      HoverCard.portalView<Message>({
        open: model.open,
        children: [
          HoverCard.backdropView<Message>({ onClose: ClosedHoverCard() }),
          HoverCard.positionerView<Message>({
            children: [
              HoverCard.popupView<Message>({
                children: [
                  h.div([h.Class(HoverCard.hoverCardAvatarClassName)], ["V"]),
                  h.h3(
                    [h.Class(HoverCard.hoverCardTitleClassName)],
                    ["@vercel"]
                  ),
                  h.p(
                    [h.Class(HoverCard.hoverCardDescriptionClassName)],
                    [
                      "The React Framework – created and maintained by @vercel.",
                    ]
                  ),
                  h.div(
                    [h.Class(HoverCard.hoverCardMetaClassName)],
                    ["Joined December 2021"]
                  ),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as HoverCardBasicExample from "./main";

describe("Hover Card Basic example", () => {
  test("opens and closes the controlled preview", () => {
    Scene.scene(
      {
        update: HoverCardBasicExample.update,
        view: HoverCardBasicExample.view,
      },
      Scene.with(HoverCardBasicExample.init()[0]),
      Scene.expect(Scene.role("dialog")).toBeAbsent(),
      Scene.click(Scene.role("button", { name: "Hover Here" })),
      Scene.expect(Scene.role("dialog")).toExist(),
      Scene.expect(Scene.text("@vercel")).toExist(),
      Scene.expect(
        Scene.text("The React Framework – created and maintained by @vercel.")
      ).toExist(),
      Scene.expect(Scene.text("Joined December 2021")).toExist(),
      Scene.click(Scene.role("button", { name: "Close hover card" })),
      Scene.expect(Scene.role("dialog")).toBeAbsent()
    );
  });
});
